preConditionHook:
// Level high volume (Brian's notes P1f, volume form, triage row P1). Pane 2. The
// P1 visit scan: a VISIT is a bar kk bars ago, minGap <= kk <= lookback, whose
// low..high range contains the current close (inclusive, el_le/el_ge). At least
// minVisits visits. Passes when the mean TOTAL ticks of the visit bars
// (ctx.Ticks[kk], the data series) is at least volumeMultiple x the
// volumeLookback-bar average of vol = Ticks. Identical both sides.
// The average is VolumeAboveAverageMultiple's block verbatim: vol is an EL
// VARIABLE, so average(vol, n) reads its zero-filled warm-up history, mirrored
// as a zero-initialized ring buffer read NEWEST-FIRST (EL's Summation order).
vol = (double)ctx.Ticks[0];
if (volHistory.size() != (std::size_t)(int)volumeLookback) {
    volHistory.assign((std::size_t)(int)volumeLookback, 0.0);
    volCursor = 0;
}
volHistory[volCursor] = vol;
volCursor = (volCursor + 1) % volHistory.size();
avgVol = 0.0;
for (vv = 0; vv < volHistory.size(); ++vv) {
    avgVol += volHistory[(volCursor + volHistory.size() - 1 - vv) % volHistory.size()];
}
avgVol /= (int)volumeLookback;
visitCount = 0;
ticksSum = 0.0;
for (kk = (int)minGap; kk <= (int)lookback; ++kk) {
    if (el_le(low[kk], close[0]) && el_ge(high[kk], close[0])) {
        visitCount = visitCount + 1;
        ticksSum = ticksSum + (double)ctx.Ticks[kk];
    }
}
meanTicks = 0.0;
if (visitCount > 0) meanTicks = ticksSum / visitCount;
enoughVisits = el_ge(visitCount, minVisits) && el_gt(visitCount, 0);
